const raw = String($input.first().json.stdout || '').trim();

if (!raw || raw === '__CONFIG_NOT_FOUND__') {
  throw new Error('Configuration not found: /data/plex-media-server/stack.json (legacy fallback also checked)');
}

let cfg;
try {
  cfg = JSON.parse(raw);
} catch (e) {
  throw new Error('Invalid configuration loader response: ' + e.message);
}

if (cfg.configError) {
  throw new Error('Invalid stack.json: ' + cfg.configError);
}

const missing = [];

if (!cfg.plexApiTokenPresent) missing.push('plex.api_token');
if (!cfg.radarrUrl) missing.push('radarr.url');
if (!cfg.radarrApiKeyPresent) missing.push('radarr.api_key');
if (!cfg.sonarrUrl) missing.push('sonarr.url');
if (!cfg.sonarrApiKeyPresent) missing.push('sonarr.api_key');

if (missing.length) {
  throw new Error('Missing fields in stack.json: ' + missing.join(', '));
}

for (const [name, value] of [
  ['radarr.url', cfg.radarrUrl],
  ['sonarr.url', cfg.sonarrUrl]
]) {
  if (!/^https?:\/\//i.test(String(value || ''))) {
    throw new Error(name + ' must be a valid HTTP(S) URL');
  }
}

return [{
  json: {
    status: 'CONFIG_OK',
    plexUrl: cfg.plexUrl,
    radarrUrl: cfg.radarrUrl,
    sonarrUrl: cfg.sonarrUrl
  }
}];

parameters.command:
node <<'NODE'
const fs=require('fs');
const cfg=JSON.parse(fs.readFileSync((['/data/plex-media-server/stack.json','/data/PlexMediaServer/stack.json','/data/video-factory/_Plex/stack.json'].find(p=>fs.existsSync(p))||'/data/plex-media-server/stack.json'),'utf8'));
const token=String(cfg.plex?.api_token||'').trim();
const STATE='/home/node/.n8n/plex-watchlist-state.json';
const SELF_PAGE=100;
const FRIEND_PAGE=100;
const sleep=ms=>new Promise(r=>setTimeout(r,ms));

if(!token){
  console.error('plex.api_token missing');
  process.exit(1);
}

const plexHeaders={
  'X-Plex-Token':token,
  'X-Plex-Product':'PLEX Bootstrap Synology',
  'X-Plex-Version':'5.0',
  'X-Plex-Client-Identifier':'plex-bootstrap-synology-v8',
  'X-Plex-Platform':'n8n',
  'Accept':'application/json'
};

async function fetchJson(url,options={},attempts=3){
  let last;
  for(let i=1;i<=attempts;i++){
    try{
      const r=await fetch(url,{...options,signal:AbortSignal.timeout(15000)});
      const txt=await r.text();
      let data;
      try{data=txt?JSON.parse(txt):{}}catch{throw new Error('Invalid JSON from '+url+' :: '+txt.slice(0,300))}
      if(!r.ok) throw new Error('HTTP '+r.status+' '+url+' :: '+txt.slice(0,300));
      return data;
    }catch(e){
      last=e;
      if(i<attempts) await sleep(500*i);
    }
  }
  throw last||new Error('Unknown HTTP error');
}

async function gql(query,variables,operationName){
  return fetchJson('https://community.plex.tv/api',{
    method:'POST',
    headers:{
      ...plexHeaders,
      'Content-Type':'application/json'
    },
    body:JSON.stringify({query,variables,operationName})
  });
}

function compact(x){
  return {
    ratingKey:String(x.ratingKey||''),
    guid:String(x.guid||''),
    type:String(x.type||'').toLowerCase(),
    title:String(x.title||'').trim(),
    year:x.year==null?null:Number(x.year),
    watchlistedAt:x.watchlistedAt??null,
    guids:Array.isArray(x.guids)?x.guids.map(String):[],
    requestedBy:Array.isArray(x.requestedBy)?[...new Set(x.requestedBy.map(String))]:[]
  };
}

function keyOf(x){
  return String(x.ratingKey||x.guid||(x.type+':'+x.title+':'+(x.year??''))).trim();
}

function readState(){
  try{
    if(!fs.existsSync(STATE)) return {version:2,initialized:false,current:[],pendingRemoved:[]};
    const x=JSON.parse(fs.readFileSync(STATE,'utf8'));
    return {
      version:2,
      initialized:Boolean(x.initialized),
      current:Array.isArray(x.current)?x.current:[],
      pendingRemoved:Array.isArray(x.pendingRemoved)?x.pendingRemoved:[]
    };
  }catch{
    return {version:2,initialized:false,current:[],pendingRemoved:[]};
  }
}

function writeState(state){
  const tmp=STATE+'.tmp';
  fs.writeFileSync(tmp,JSON.stringify(state,null,2));
  fs.renameSync(tmp,STATE);
}

async function getSelfWatchlist(){
  const items=[];
  let start=0,total=null,complete=true,pages=0;

  for(let page=0;page<50;page++){
    const url=new URL('https://discover.provider.plex.tv/library/sections/watchlist/all');
    url.searchParams.set('includeCollections','1');
    url.searchParams.set('includeExternalMedia','1');
    url.searchParams.set('sort','watchlistedAt:desc');

    const data=await fetchJson(url,{
      headers:{
        ...plexHeaders,
        'X-Plex-Container-Start':String(start),
        'X-Plex-Container-Size':String(SELF_PAGE)
      }
    });

    const mc=data.MediaContainer||{};
    if(total==null){
      const n=Number(mc.totalSize??mc.total??mc.size);
      total=Number.isFinite(n)?n:null;
    }

    const rows=[]
      .concat(Array.isArray(mc.Metadata)?mc.Metadata:[])
      .concat(Array.isArray(mc.Video)?mc.Video:[])
      .concat(Array.isArray(mc.Directory)?mc.Directory:[]);

    pages++;
    if(!rows.length) break;

    for(const x of rows){
      const type=String(x.type||'').toLowerCase();
      if(!['movie','show'].includes(type)) continue;
      const title=String(x.title||'').trim();
      if(!title) continue;

      const guids=Array.isArray(x.Guid)?x.Guid.map(g=>String(g.id||'')).filter(Boolean):[];

      items.push(compact({
        ratingKey:x.ratingKey,
        guid:x.guid,
        type,
        title,
        year:x.year,
        watchlistedAt:x.watchlistedAt,
        guids,
        requestedBy:['self']
      }));
    }

    start+=rows.length;
    if(rows.length<SELF_PAGE) break;
    if(total!=null&&start>=total) break;
    if(page===49) complete=false;
  }

  if(total!=null&&start<total) complete=false;
  return {items,complete,total:total??items.length,pages};
}

const qFriends=[
  'query GetAllFriends {',
  '  allFriendsV2 {',
  '    user {',
  '      id',
  '      username',
  '    }',
  '  }',
  '}'
].join('\n');

const qWatch=[
  'query GetWatchlistHub ($uuid: ID = "", $first: PaginationInt!, $after: String) {',
  '  user(id: $uuid) {',
  '    watchlist(first: $first, after: $after) {',
  '      nodes {',
  '        ...itemFields',
  '      }',
  '      pageInfo {',
  '        hasNextPage',
  '        endCursor',
  '      }',
  '    }',
  '  }',
  '}',
  'fragment itemFields on MetadataItem {',
  '  id',
  '  title',
  '  type',
  '}'
].join('\n');

async function enrichFriendItem(friend,item){
  const id=String(item?.id||'').trim();
  if(!id) throw new Error('Friend item has no Plex ID');

  const data=await fetchJson('https://discover.provider.plex.tv/library/metadata/'+encodeURIComponent(id),{
    headers:plexHeaders
  });

  const m=data?.MediaContainer?.Metadata?.[0];
  if(!m) throw new Error('Plex metadata not found for '+id);

  const type=String(m.type||item.type||'').toLowerCase();
  const guids=Array.isArray(m.Guid)?m.Guid.map(g=>String(g.id||'')).filter(Boolean):[];

  return compact({
    ratingKey:m.ratingKey||id,
    guid:m.guid||'',
    type,
    title:m.title||item.title||'',
    year:m.year,
    guids,
    requestedBy:['@'+String(friend.username||friend.id)]
  });
}

async function getFriendsWatchlists(){
  const result={items:[],complete:true,friends:[],errors:[]};

  let friends;
  try{
    const fd=await gql(qFriends,{},'GetAllFriends');
    if(fd?.errors?.length) throw new Error(JSON.stringify(fd.errors).slice(0,500));
    friends=(fd?.data?.allFriendsV2||[]).map(x=>x?.user).filter(Boolean);
  }catch(e){
    result.complete=false;
    result.errors.push('friends: '+e.message);
    return result;
  }

  for(const friend of friends){
    let after=null,pages=0,count=0;
    const rawItems=[];

    try{
      do{
        const vars={uuid:String(friend.id),first:FRIEND_PAGE};
        if(after) vars.after=after;

        const wd=await gql(qWatch,vars,'GetWatchlistHub');
        if(wd?.errors?.length) throw new Error(JSON.stringify(wd.errors).slice(0,500));

        const wl=wd?.data?.user?.watchlist;
        const nodes=Array.isArray(wl?.nodes)?wl.nodes:[];

        rawItems.push(...nodes);
        count+=nodes.length;
        pages++;

        if(wl?.pageInfo?.hasNextPage&&wl?.pageInfo?.endCursor){
          after=wl.pageInfo.endCursor;
        }else{
          after=null;
        }

        if(pages>=20&&after){
          result.complete=false;
          result.errors.push('pagination '+String(friend.username||friend.id)+' limited to 20 pages');
          break;
        }
      }while(after);

      for(let i=0;i<rawItems.length;i+=8){
        const batch=rawItems.slice(i,i+8);
        const enriched=await Promise.allSettled(batch.map(item=>enrichFriendItem(friend,item)));

        for(const r of enriched){
          if(r.status==='fulfilled'){
            const type=String(r.value.type||'').toLowerCase();
            if(['movie','show'].includes(type)&&r.value.title) result.items.push(r.value);
          }else{
            result.complete=false;
            result.errors.push(String(friend.username||friend.id)+': '+r.reason.message);
          }
        }
      }
    }catch(e){
      result.complete=false;
      result.errors.push(String(friend.username||friend.id)+': '+e.message);
    }

    result.friends.push({
      id:String(friend.id||''),
      username:String(friend.username||''),
      count,
      pages
    });
  }

  return result;
}

function mergeItems(items){
  const map=new Map();

  for(const raw of items){
    const item=compact(raw);
    const key=keyOf(item);
    if(!key) continue;

    const previous=map.get(key);
    if(!previous){
      map.set(key,item);
      continue;
    }

    map.set(key,{
      ...previous,
      ...item,
      watchlistedAt:previous.watchlistedAt??item.watchlistedAt??null,
      guids:[...new Set([...(previous.guids||[]),...(item.guids||[])])],
      requestedBy:[...new Set([...(previous.requestedBy||[]),...(item.requestedBy||[])])]
    });
  }

  return [...map.values()];
}

(async()=>{
  const self=await getSelfWatchlist();

  let social;
  try{
    social=await getFriendsWatchlists();
  }catch(e){
    social={items:[],complete:false,friends:[],errors:[e.message]};
  }

  const current=mergeItems([...self.items,...social.items]);
  const complete=self.complete&&social.complete;

  const prev=readState();
  let pending=Array.isArray(prev.pendingRemoved)?prev.pendingRemoved.slice():[];

  if(complete){
    const currentKeys=new Set(current.map(keyOf));
    const map=new Map(pending.map(x=>[keyOf(x),x]).filter(([k])=>Boolean(k)));

    if(prev.initialized){
      for(const old of prev.current){
        const k=keyOf(old);
        if(k&&!currentKeys.has(k)) map.set(k,compact(old));
      }
    }

    for(const cur of current) map.delete(keyOf(cur));
    pending=[...map.values()];

    writeState({
      version:2,
      initialized:true,
      updatedAt:new Date().toISOString(),
      source:'self+friends',
      current,
      pendingRemoved:pending
    });
  }

  console.log(JSON.stringify({
    service:'plex-discover',
    mode:'multi-user-stateful-reconcile',
    complete,
    count:current.length,
    selfCount:self.items.length,
    selfReportedTotal:self.total,
    friendCount:social.friends.length,
    friendItemCount:social.items.length,
    friends:social.friends,
    socialErrors:social.errors,
    initializedBefore:prev.initialized,
    pendingRemovedCount:complete?pending.length:prev.pendingRemoved.length,
    items:current,
    removed:complete?pending:[]
  }));
})().catch(e=>{
  console.error('Plex multi-user watchlist: '+e.message);
  process.exit(1);
});
