parameters.jsCode:
const raw = String($input.first().json.stdout || '').trim();
let payload;
try { payload = JSON.parse(raw); }
catch (e) { throw new Error('Invalid Plex response: ' + e.message); }

const source = Array.isArray(payload.items) ? payload.items : [];
const removed = Array.isArray(payload.removed) ? payload.removed : [];
const output = [];
const dedup = new Set();
const nowIso = new Date().toISOString();

for (const src of source) {
  const type = String(src.type || '').toLowerCase();
  if (type !== 'movie' && type !== 'show') continue;

  const title = String(src.title || '').trim();
  if (!title) continue;

  const key = String(src.ratingKey || src.guid || (type + ':' + title + ':' + (src.year ?? ''))).trim();
  if (!key || dedup.has(key)) continue;
  dedup.add(key);

  const item = {
    key,
    type,
    title,
    year: src.year == null ? null : Number(src.year),
    ratingKey: String(src.ratingKey || ''),
    guid: String(src.guid || ''),
    guids: Array.isArray(src.guids) ? src.guids.map(String) : [],
    requestedBy: Array.isArray(src.requestedBy) ? src.requestedBy.map(String) : [],
    watchlistedAt: src.watchlistedAt ?? null,
    reconciledAt: nowIso
  };

  output.push({
    json: {
      ...item,
      _action: 'present',
      _payloadB64: Buffer.from(JSON.stringify(item), 'utf8').toString('base64')
    }
  });
}

if (payload.complete !== false && removed.length) {
  output.push({
    json: {
      _action: 'removed_batch',
      removedCount: removed.length,
      _payloadB64: Buffer.from(JSON.stringify(removed), 'utf8').toString('base64')
    }
  });
}

return output;

parameters.command:
=INPUT_B64='{{ $json._payloadB64 }}' node <<'NODE'
const fs=require('fs');
const path=require('path');
const input=JSON.parse(Buffer.from(String(process.env.INPUT_B64||''),'base64').toString('utf8'));
const cfg=JSON.parse(fs.readFileSync((['/data/plex-media-server/stack.json','/data/PlexMediaServer/stack.json','/data/video-factory/_Plex/stack.json'].find(p=>fs.existsSync(p))||'/data/plex-media-server/stack.json'),'utf8'));
const BASE=String(cfg.radarr?.url||'').replace(/\/$/,'');
const API_KEY=String(cfg.radarr?.api_key||'').trim();
const ROOT='/volume1/VideoFactory/_Plex/media/Movies';
const PROFILE=4;
const SEARCH_COOLDOWN_MS=60*60*1000;
const VIDEO_EXT=new Set(['.mkv','.mp4','.avi','.m4v','.mov','.ts','.m2ts','.webm','.wmv']);
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function api(p,options={},attempts=3){
  let last;
  for(let i=1;i<=attempts;i++){
    try{
      const r=await fetch(BASE+p,{...options,headers:{'X-Api-Key':API_KEY,'Accept':'application/json','Content-Type':'application/json',...(options.headers||{})},signal:AbortSignal.timeout(10000)});
      const txt=await r.text(); let data=null; try{data=txt?JSON.parse(txt):null}catch{data=txt}
      if(r.ok) return data;
      const retryable=r.status===429||r.status>=500;
      const e=new Error('HTTP '+r.status+' '+p+' :: '+String(txt).slice(0,300));
      if(!retryable||i===attempts) throw e; last=e;
    }catch(e){last=e;if(i===attempts) throw e;}
    await sleep(500*i);
  }
  throw last||new Error('Unknown Radarr API error');
}

async function grabMovieRelease(movieId){
  const [releases,clients]=await Promise.all([
    api('/api/v3/release?movieId='+encodeURIComponent(movieId)),
    api('/api/v3/downloadclient')
  ]);
  function isFrenchRelease(r){
    const title=String(r?.title||'');
    const explicitFrench=/\b(TRUEFRENCH|FRENCH|VFF|VF2|VFI|VOF|VOSTFR|FRFR)\b/i.test(title);
    const vfq=/\bVFQ\b/i.test(title);
    const voOnly=/\bVO\b/i.test(title) && !/\bVOSTFR\b/i.test(title);
    const langs=Array.isArray(r?.languages)?r.languages:[];
    const frenchMetadata=langs.some(l=>{
      const value=String(l?.name||l?.language||l||'').toLowerCase();
      return value.includes('french')||value==='fr'||value==='fra';
    });
    return !vfq && !voOnly && (explicitFrench||frenchMetadata);
  }
  const candidates=(Array.isArray(releases)?releases:[]).filter(r=>{
    const torrent=Boolean(r.magnetUrl||r.infoHash)||String(r.protocol||'').toLowerCase()==='torrent';
    return torrent && r.downloadAllowed!==false && r.rejected!==true && r.temporarilyRejected!==true && isFrenchRelease(r);
  });
  if(!candidates.length) return {grabbed:false,status:'NO_ACCEPTABLE_RELEASE'};
  const release=candidates[0];
  const decy=(Array.isArray(clients)?clients:[]).find(c=>String(c.name||'').toLowerCase()==='decypharr'&&c.enable!==false);
  const qbit=(Array.isArray(clients)?clients:[]).find(c=>{
    const impl=String(c.implementation||'').toLowerCase();
    return impl==='qbittorrent'&&String(c.name||'').toLowerCase()!=='decypharr'&&c.enable!==false;
  });
  if(!decy&&!qbit) return {grabbed:false,status:'NO_DOWNLOAD_CLIENT'};
  async function grab(client){
    const response=await fetch(BASE+'/api/v3/release',{
      method:'POST',
      headers:{'X-Api-Key':API_KEY,'Accept':'application/json','Content-Type':'application/json'},
      body:JSON.stringify({...release,downloadClientId:Number(client.id)}),
      signal:AbortSignal.timeout(20000)
    });
    const text=await response.text();
    let data=null; try{data=text?JSON.parse(text):null}catch{data=text}
    return {ok:response.ok,status:response.status,data,text};
  }
  if(decy){
    const first=await grab(decy);
    if(first.ok) return {grabbed:true,status:'GRABBED',downloadClient:'Decypharr',downloadClientId:decy.id,fallbackUsed:false,releaseTitle:release.title};
    if((first.status===400||first.status===409)&&qbit){
      const fallback=await grab(qbit);
      if(fallback.ok) return {grabbed:true,status:'GRABBED_FALLBACK',downloadClient:qbit.name||'qBittorrent',downloadClientId:qbit.id,fallbackUsed:true,decypharrStatus:first.status,releaseTitle:release.title};
      return {grabbed:false,status:'FALLBACK_FAILED',decypharrStatus:first.status,qbittorrentStatus:fallback.status,error:String(fallback.text||'').slice(0,300),releaseTitle:release.title};
    }
    return {grabbed:false,status:'DECYPHARR_FAILED_NO_FALLBACK',decypharrStatus:first.status,error:String(first.text||'').slice(0,300),releaseTitle:release.title};
  }
  const fallback=await grab(qbit);
  return fallback.ok
    ? {grabbed:true,status:'GRABBED_QBIT_ONLY',downloadClient:qbit.name||'qBittorrent',downloadClientId:qbit.id,fallbackUsed:true,releaseTitle:release.title}
    : {grabbed:false,status:'QBIT_FAILED',qbittorrentStatus:fallback.status,error:String(fallback.text||'').slice(0,300),releaseTitle:release.title};
}

function extractGuid(prefix){
  for(const value of (Array.isArray(input.guids)?input.guids:[])){
    const m=String(value).match(new RegExp('^'+prefix+':\\/\\/(\\d+)$','i'));
    if(m) return Number(m[1]);
  }
  return null;
}
function localPath(nas){
  const prefix='/volume1/VideoFactory'; const p=String(nas||'');
  if(!p.startsWith(prefix)) throw new Error('Radarr path outside VideoFactory: '+p);
  return '/data/video-factory'+p.slice(prefix.length);
}
function hasVideo(dir){
  if(!fs.existsSync(dir)) return false;
  const st=fs.statSync(dir);
  if(st.isFile()) return VIDEO_EXT.has(path.extname(dir).toLowerCase());
  for(const name of fs.readdirSync(dir)){
    const p=path.join(dir,name); const s=fs.statSync(p);
    if(s.isDirectory()){ if(hasVideo(p)) return true; }
    else if(s.isFile()&&VIDEO_EXT.has(path.extname(name).toLowerCase())) return true;
  }
  return false;
}
async function waitCommand(id){
  if(!id) return null;
  for(let i=0;i<20;i++){
    const c=await api('/api/v3/command/'+id);
    const status=String(c?.status||'').toLowerCase();
    if(['completed','failed','aborted'].includes(status)) return c;
    await sleep(500);
  }
  return null;
}
(async()=>{
  if(input.type!=='movie') throw new Error('Unexpected Plex type for Radarr: '+input.type);
  if(!BASE||!API_KEY) throw new Error('Incomplete Radarr configuration');
  const [profile,roots]=await Promise.all([api('/api/v3/qualityprofile/'+PROFILE),api('/api/v3/rootfolder')]);
  if(!profile||Number(profile.id)!==PROFILE) throw new Error('Radarr quality profile ID '+PROFILE+' not found');
  let root=Array.isArray(roots)?roots.find(x=>String(x.path||'').replace(/\/$/,'')===ROOT):null;
  if(!root) root=await api('/api/v3/rootfolder',{method:'POST',body:JSON.stringify({path:ROOT})});
  if(!root?.id) throw new Error('Radarr root folder unavailable: '+ROOT);

  const tmdbFromPlex=extractGuid('tmdb');
  let hit=null, existing=[];
  if(tmdbFromPlex){
    existing=await api('/api/v3/movie?tmdbId='+encodeURIComponent(tmdbFromPlex));
    if(!Array.isArray(existing)) existing=[];
    if(!existing.length){
      const lookup=await api('/api/v3/movie/lookup?term='+encodeURIComponent('tmdb:'+tmdbFromPlex));
      hit=Array.isArray(lookup)?lookup[0]||null:null;
    }
  }else{
    const term=[input.title,input.year||''].join(' ').trim();
    const lookup=await api('/api/v3/movie/lookup?term='+encodeURIComponent(term));
    const rows=Array.isArray(lookup)?lookup:[];
    hit=rows.find(x=>Number(x.year)===Number(input.year)&&String(x.title||'').toLowerCase()===String(input.title||'').toLowerCase())
      ||rows.find(x=>Number(x.year)===Number(input.year))||rows[0]||null;
    if(hit?.tmdbId){ existing=await api('/api/v3/movie?tmdbId='+encodeURIComponent(hit.tmdbId)); if(!Array.isArray(existing)) existing=[]; }
  }

  if(existing.length){
    let movie=existing[0];
    if(!movie?.id) throw new Error('Existing Radarr movie has no internal ID');
