    }

    const [queue,commands]=await Promise.all([api('/api/v3/queue?page=1&pageSize=100&includeUnknownMovieItems=true'),api('/api/v3/command')]);
    const activeDownload=(queue?.records||[]).some(x=>Number(x.movieId)===Number(movie.id));
    const activeSearch=(Array.isArray(commands)?commands:[]).some(c=>{
      const status=String(c.status||'').toLowerCase();
